### **3. Code**

Here is the code for each file. I've included detailed comments explaining every part of the logic.

#### **`server/programs.json`** (Our Data)

This file contains our sample data based on your "selection criteria."

```json
[
  {
    "id": 1,
    "name": "TechCorp VRP",
    "url": "https://example.com/bugbounty",
    "min_bounty": 100,
    "max_bounty": 15000,
    "asset_types": ["web", "api", "ios"],
    "safe_harbor": true,
    "reputation": "Good"
  },
  {
    "id": 2,
    "name": "FinSecure Program",
    "url": "https://example.com/security",
    "min_bounty": 500,
    "max_bounty": 50000,
    "asset_types": ["web", "android"],
    "safe_harbor": true,
    "reputation": "Excellent"
  },
  {
    "id": 3,
    "name": "GameFun Co. Bugs",
    "url": "https://example.com/gamers/bugs",
    "min_bounty": 50,
    "max_bounty": 2000,
    "asset_types": ["web", "windows-app"],
    "safe_harbor": false,
    "reputation": "New"
  },
  {
    "id": 4,
    "name": "DataGiant Cloud Security",
    "url": "https://example.com/datagiant/vrp",
    "min_bounty": 250,
    "max_bounty": 20000,
    "asset_types": ["api", "cloud-infra"],
    "safe_harbor": true,
    "reputation": "Good"
  }
]
```

#### **`server/server.js`** (The Backend API)

```javascript
// Import required libraries
const express = require('express');
const cors = require('cors');

// Load our bug bounty program data from the JSON file
const programsData = require('./programs.json');

// Initialize the Express application
const app = express();
const PORT = process.env.PORT || 5000; // Use port 5000 for our backend

// --- Middleware ---
// Enable Cross-Origin Resource Sharing (CORS) so our React frontend (running on a different port)
// can communicate with this backend.
app.use(cors());

// --- API Endpoints ---

/**
 * @route   GET /api/programs
 * @desc    Get bug bounty programs, with optional filtering
 * @access  Public
 * 
 * This is the core endpoint of our application. It supports filtering based
 * on query parameters in the URL.
 * Example queries:
 * /api/programs?keyword=corp
 * /api/programs?minBounty=200
 * /api/programs?assetType=web
 * /api/programs?minBounty=100&assetType=api
 */
app.get('/api/programs', (req, res) => {
  // Start with the full list of programs
  let filteredPrograms = [...programsData];

  // Destructure query parameters from the request
  const { keyword, minBounty, assetType } = req.query;

  // --- Apply Filters ---

  // 1. Keyword Filter: Search in the program name. Case-insensitive.
  if (keyword) {
    filteredPrograms = filteredPrograms.filter(program =>
      program.name.toLowerCase().includes(keyword.toLowerCase())
    );
  }

  // 2. Minimum Bounty Filter:
  if (minBounty) {
    // We only include programs where the *maximum* possible bounty is greater
    // than or equal to the desired minimum. This is a common way to filter.
    const bounty = parseInt(minBounty, 10);
    if (!isNaN(bounty)) {
      filteredPrograms = filteredPrograms.filter(program => program.max_bounty >= bounty);
    }
  }

  // 3. Asset Type Filter:
  if (assetType) {
    // Check if the program's array of asset_types includes the requested type.
    filteredPrograms = filteredPrograms.filter(program =>
      program.asset_types.includes(assetType.toLowerCase())
    );
  }

  // Return the filtered list as a JSON response
  res.json(filteredPrograms);
});

// --- Server Activation ---
app.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```

